        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def gcd(a, b):
    return math.gcd(a, b)

def generator(rng):
    while True:
        m = rng.randint(2, 6)
        n = rng.randint(m + 1, m + 7)

        common_divisor = gcd(m, n)
        m //= common_divisor
        n //= common_divisor

        if m == n: continue

        # Area formula is (2 * L^2 * m * n) / (n^2 - m^2)
        # To get an integer area, we need to choose L appropriately.
        num_template = 2 * m * n
        den_template = n*n - m*m

        common_divisor_2 = gcd(num_template, den_template)
        num_reduced = num_template // common_divisor_2
        den_reduced = den_template // common_divisor_2

        # We need den_reduced | L^2. Find smallest L_mult such that den_reduced | L_mult^2.
        L_mult = 1
        temp_den = den_reduced
        i = 2
        while i * i <= temp_den:
            if temp_den % i == 0:
                p_count = 0
                while temp_den % i == 0:
                    p_count += 1
                    temp_den //= i
                L_mult *= i ** ((p_count + 1) // 2)
            i += 1
        if temp_den > 1:
            L_mult *= temp_den

        k_L = rng.randint(1, 4)
        L = L_mult * k_L

        area_val = (2 * L*L * m * n) / (n*n - m*m)
        if area_val > 5000 or area_val < 20: # Keep answer in a reasonable range
            continue

        # Ensure the problem is not one of the most basic cases
        if m == 1 and n == 2 and L < 10:
            continue

        return {'m': m, 'n': n, 'L': L}

        import math

def verifier(assign):
    m = assign['m']
    n = assign['n']
    L = assign['L']

    if not (isinstance(m, int) and isinstance(n, int) and isinstance(L, int)):
        # All parameters must be integers.
        return False, None
    if not (m > 0 and n > 0 and L > 0):
        # All parameters must be positive.
        return False, None
    if m >= n:
        # Ratio should be simplified to have n > m (or problem needs abs value).
        # Generator ensures n > m, so this is a check for malformed assignments.
        return False, None

    # The maximum area is given by the formula (2 * L^2 * m * n) / (n^2 - m^2)
    numerator = 2 * L * L * m * n
    denominator = n * n - m * m

    if denominator == 0:
        # m cannot equal n, otherwise the area is unbounded.
        return False, None

    if numerator % denominator != 0:
        # The problem is constructed to have an integer answer.
        return False, None

    answer = numerator // denominator

    if answer <= 0:
        return False, None

    # Reject trivial instances sometimes generated by simple parameters
    if m == 1 and n == 2 and L % 3 == 0 and L < 10:
        return False, None

    return True, int(answer)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
